Java.fragment:
Linker linker = Linker.nativeLinker();
MemorySegment symbol = linker.defaultLookup().findOrThrow("abs");
MethodHandle abs = linker.downcallHandle(symbol, FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
int result = (int) abs.invokeExact(-3);
return result;

